/**
 * Validator core: mirrors jsonschema.validators.validator_for and the
 * generated Validator classes (iter_errors / is_valid / descend).
 */

import { PyFloat } from './json_parse.mjs';
import { hasOwn, isPlainObject } from './pytypes.mjs';
import { createResolver } from './resolver.mjs';
import { ERR } from './keywords.mjs';
import { DEFAULT_VALIDATOR, META_ID_INDEX } from './drafts.mjs';

export class Validator {
  constructor(schema, klass) {
    this.schema = schema;
    this.klass = klass;
    this.resolver = createResolver(schema);
  }

  /** Type check against this draft's type checker. Unknown type names
   *  raise, like jsonschema's UndefinedTypeCheck. */
  isType(instance, type) {
    const u = instance instanceof PyFloat ? instance.value : instance;
    switch (type) {
      case 'array':
        return Array.isArray(u);
      case 'boolean':
        return typeof u === 'boolean';
      case 'integer': {
        if (typeof u === 'bigint') return true;
        if (typeof u !== 'number' || !Number.isInteger(u)) return false;
        if (this.klass.integerStrict && instance instanceof PyFloat) return false;
        return true;
      }
      case 'number':
        return typeof u === 'number' || typeof u === 'bigint';
      case 'null':
        return u === null;
      case 'object':
        return isPlainObject(instance);
      case 'string':
        return typeof u === 'string';
      case 'any':
        if (this.klass.allowAny) return true;
        throw new Error(`Type checker for ${type} is undefined`);
      default:
        throw new Error(`Type checker for ${type} is undefined`);
    }
  }

  *iterErrors(instance, schema = this.schema) {
    if (schema === true) return;
    if (schema === false) {
      yield ERR;
      return;
    }
    if (!isPlainObject(schema)) {
      throw new TypeError('schema must be an object or a boolean');
    }
    const keywords = this.klass.keywords;
    // Drafts 3-7: a "$ref" keyword overrides all of its siblings.
    if (this.klass.refOverrides && hasOwn(schema, '$ref')) {
      yield* keywords.$ref(this, schema.$ref, instance, schema);
      return;
    }
    for (const key of Object.keys(schema)) {
      const fn = keywords[key];
      if (fn === undefined) continue;
      yield* fn(this, schema[key], instance, schema);
    }
  }

  *descend(instance, schema) {
    yield* this.iterErrors(instance, schema);
  }

  isValidUnder(schema, instance) {
    for (const _ of this.iterErrors(instance, schema)) return false;
    return true;
  }

  isValid(instance) {
    return this.isValidUnder(this.schema, instance);
  }

  resolveRef(ref) {
    return this.resolver.resolve(ref);
  }
}

/** Mirror of jsonschema.validators.validator_for: picks the validator
 *  class from the schema's "$schema" keyword, defaulting to the latest
 *  draft (2020-12) when absent, unknown, or the schema is a boolean. */
export function validatorFor(schema) {
  if (schema === true || schema === false || !isPlainObject(schema) || !hasOwn(schema, '$schema')) {
    return DEFAULT_VALIDATOR;
  }
  const id = schema.$schema;
  if (typeof id !== 'string') {
    throw new TypeError('the $schema keyword must be a string');
  }
  // jsonschema's URIDict normalizes by stripping the fragment.
  const normalized = id.split('#')[0];
  const found = META_ID_INDEX.get(normalized);
  if (found !== undefined) return found;
  process.stderr.write(
    'test13.py:15: DeprecationWarning: The metaschema specified by $schema was not found. ' +
      'Using the latest draft to validate, but this will raise an error in the future.\n',
  );
  return DEFAULT_VALIDATOR;
}

