/**
 * Minimal argparse replica covering exactly the two required options of
 * the source script: --a and --b (both required, both take one value),
 * plus -h/--help. Supports "--opt value" and "--opt=value", unique
 * prefix abbreviations, argparse-style error messages and exit codes.
 */

import { basename } from 'node:path';

const LONG_OPTIONS = ['--a', '--b', '--help'];
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

export function parseArgs(argv) {
  const prog = basename(process.argv[1] || 'test13.mjs');
  const usage = `usage: ${prog} [-h] --a A --b B`;

  const error = (msg) => {
    process.stderr.write(`${usage}\n${prog}: error: ${msg}\n`);
    process.exit(2);
  };

  const printHelp = () => {
    process.stdout.write(
      `${usage}\n` +
        '\n' +
        'options:\n' +
        '  -h, --help  show this help message and exit\n' +
        '  --a A       instance (JSON string)\n' +
        '  --b B       schema (JSON string)\n',
    );
    process.exit(0);
  };

  const looksLikeOption = (tok) => {
    if (!tok.startsWith('-') || tok === '-') return false;
    if (NEGATIVE_NUMBER_RE.test(tok)) return false;
    return true;
  };

  const values = Object.create(null);
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const tok = argv[i];
    if (tok === '--') {
      i++;
      while (i < argv.length) extras.push(argv[i++]);
      break;
    }
    if (tok === '-h') printHelp();
    if (tok.startsWith('--')) {
      let name = tok;
      let inlineVal;
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        name = tok.slice(0, eq);
        inlineVal = tok.slice(eq + 1);
      }
      let matched = null;
      if (LONG_OPTIONS.includes(name)) {
        matched = name;
      } else {
        const candidates = LONG_OPTIONS.filter((o) => o.startsWith(name));
        if (candidates.length === 1) matched = candidates[0];
        else if (candidates.length > 1) {
          error(`ambiguous option: ${name} could match ${candidates.join(', ')}`);
        } else {
          extras.push(tok);
          i++;
          continue;
        }
      }
      if (matched === '--help') printHelp();
      const dest = matched.slice(2);
      if (inlineVal !== undefined) {
        values[dest] = inlineVal;
        i++;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        error(`argument ${matched}: expected one argument`);
      }
      values[dest] = next;
      i += 2;
      continue;
    }
    extras.push(tok);
    i++;
  }

  const missing = [];
  if (!('a' in values)) missing.push('--a');
  if (!('b' in values)) missing.push('--b');
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a: values.a, b: values.b };
}

