/**
 * Node.js (ESM) port of /workspace/dataset/jsonschema/test13.py.
 *
 * Parses --a (instance JSON string) and --b (schema JSON string), picks
 * the appropriate JSON Schema validator class via validator_for, then
 * prints the class name, the is_valid result and the error count.
 */

import { parseArgs } from './lib/cli.mjs';
import { pyJsonParse } from './lib/json_parse.mjs';
import { Validator, validatorFor } from './lib/validators.mjs';

const args = parseArgs(process.argv.slice(2));

const instance = pyJsonParse(args.a);
const schema = pyJsonParse(args.b);

// Use validator_for to get appropriate validator class
const validatorClass = validatorFor(schema);
const validator = new Validator(schema, validatorClass);

const result = validator.isValid(instance);
const errors = [...validator.iterErrors(instance)];

console.log(validatorClass.__name__);
console.log(result ? 'True' : 'False');
console.log(errors.length);

