  const extras = propertyExtras(instance, schema);
  if (isPlainObject(aP) || aP === true) {
    for (const key of extras) {
      yield* validator.descend(instance[key], aP);
    }
  } else if (!pyTruthy(aP) && extras.length > 0) {
    // jsonschema yields a single error listing all extra properties.
    yield ERR;
  }
}

