// Random schema/instance generator for differential fuzzing.
// Prints N lines, each: instanceJSON \t schemaJSON
import { writeSync } from 'node:fs';

let seed = Number(process.argv[3] || 42);
function rnd() {
  // xorshift32
  seed ^= seed << 13; seed >>>= 0;
  seed ^= seed >> 17;
  seed ^= seed << 5; seed >>>= 0;
  return seed / 0xffffffff;
}
function pick(arr) { return arr[Math.floor(rnd() * arr.length)]; }
function maybe(p) { return rnd() < p; }

const SCHEMA_URIS = [
  null, null, null,
  'http://json-schema.org/draft-04/schema#',
  'http://json-schema.org/draft-06/schema#',
  'http://json-schema.org/draft-07/schema#',
  'https://json-schema.org/draft/2019-09/schema',
  'https://json-schema.org/draft/2020-12/schema',
];

function randomInstance(depth) {
  const r = rnd();
  if (depth <= 0 || r < 0.45) {
    return pick([1, 2, 0, -3, 1.5, 2.0, 'a', 'abc', '', true, false, null, '2021-01-01', '😀x']);
  }
  if (r < 0.72) {
    const n = Math.floor(rnd() * 4);
    return Array.from({ length: n }, () => randomInstance(depth - 1));
  }
  const keys = ['a', 'b', 'c', 'foo'];
  const n = Math.floor(rnd() * 4);
  const obj = {};
  for (let i = 0; i < n; i++) obj[pick(keys)] = randomInstance(depth - 1);
  return obj;
}

function randomSchema(depth) {
  if (depth <= 0 || maybe(0.3)) {
    return pick([
      true, false, {},
      { type: pick(['integer', 'number', 'string', 'boolean', 'null', 'array', 'object']) },
      { type: [pick(['integer', 'string']), pick(['null', 'boolean'])] },
      { minimum: Math.floor(rnd() * 5) - 1 },
      { maximum: Math.floor(rnd() * 5) },
      { minLength: Math.floor(rnd() * 3) },
      { maxLength: Math.floor(rnd() * 4) },
      { enum: [1, 'a', null, [1]] },
      { const: pick([1, 'a', true, [1, 2]]) },
      { multipleOf: pick([1, 2, 0.5]) },
    ]);
  }
  const choice = Math.floor(rnd() * 12);
  switch (choice) {
    case 0: return { properties: { a: randomSchema(depth - 1), b: randomSchema(depth - 1) } };
    case 1: return { items: randomSchema(depth - 1) };
    case 2: return { allOf: [randomSchema(depth - 1), randomSchema(depth - 1)] };
    case 3: return { anyOf: [randomSchema(depth - 1), randomSchema(depth - 1)] };
    case 4: return { oneOf: [randomSchema(depth - 1), randomSchema(depth - 1)] };
    case 5: return { not: randomSchema(depth - 1) };
    case 6: return { required: ['a', 'b'].filter(() => maybe(0.7)) };
    case 7: return {
      properties: { a: randomSchema(depth - 1) },
      additionalProperties: maybe(0.5) ? false : randomSchema(depth - 1),
    };
    case 8: return { patternProperties: { '^a': randomSchema(depth - 1) } };
    case 9: return {
      properties: { a: randomSchema(depth - 1) },
      required: maybe(0.5) ? ['a'] : [],
      minProperties: maybe(0.5) ? 1 : undefined,
      maxItems: undefined,
    };
    case 10: return { contains: randomSchema(depth - 1), minItems: maybe(0.5) ? 1 : undefined };
    default: return {
      properties: { a: randomSchema(depth - 1), foo: randomSchema(depth - 1) },
      items: randomSchema(depth - 1),
    };
  }
}

const count = Number(process.argv[2] || 300);
const lines = [];
for (let i = 0; i < count; i++) {
  const instance = randomInstance(3);
  const schema = randomSchema(3);
  const uri = pick(SCHEMA_URIS);
  if (uri !== null) schema.$schema = uri;
  // JSON.stringify drops undefined values, like a normal schema
  lines.push(JSON.stringify(instance) + '\t' + JSON.stringify(schema));
}
writeSync(1, lines.join('\n') + '\n');

