args.new_string:
/** Python-style modulo (%), keeping BigInt precision where possible. */
export function numericMod(a, b) {
  const ua = unbox(a);
  const ub = unbox(b);
  if (typeof ua === 'bigint' || typeof ub === 'bigint') {
    const toBig = (v) => {
      if (typeof v === 'bigint') return v;
      if (typeof v === 'number' && Number.isFinite(v) && Number.isInteger(v)) return BigInt(v);
      return null;
    };
    const ba = toBig(ua);
    const bb = toBig(ub);
    if (ba !== null && bb !== null) return ba % bb;
    const fa = typeof ua === 'bigint' ? Number(ua) : ua;
    const fb = typeof ub === 'bigint' ? Number(ub) : ub;
    return fa % fb;
  }
  return ua % ub;
}

